from collections import defaultdict

def floyd_warshall(inp):
    n = len(inp)
    distance = [[float('inf')] * n for _ in range(n)]

    for i in range(n):
        distance[i][i] = 0

    for u, v, d in inp:
        distance[u-1][v-1] = d

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if distance[i][j] > distance[i][k] + distance[k][j]:
                    distance[i][j] = distance[i][k] + distance[k][j]

    return distance

def main(inp):
    n, m = inp[:2]
    inp = inp[2:]
    couples = []
    s = None
    t = None

    for l in inp:
        links = l.split()
        from_city = int(links[0])
        to_city = int(links[1])
        length = int(links[2])

        if from_city < to_city:
            couples.append((from_city, to_city))
        elif from_city > to_city:
            couples.append((to_city, from_city))
        route = floyd_warshall(couples + [(s, t), (t, s), (s, t).reverse()])
        total = 0

        for i in range(2):
            for j in range(2):
                if route[i][j] <= length:
                    total += 1

        s = from_city
        t = to_city

    return total

