class BooleanFormula:
    def __init__(self, clauses):
        self.clauses = clauses

    def count_satisfying_ways(self):
        num_variables = max(abs(x) for x, _ in self.clauses)
        modulo = 10**9 + 7

        def compute_expression_once():
            # Collect variables and their counts
            variable_counts = [0] * (num_variables + 1)
            for clause in self.clauses:
                for literal, _ in clause:
                    if literal > 0:
                        variable_counts[abs(literal)] += 1
                    else:
                        variable_counts[-abs(literal)] += 1

            # Initialize the number of ways
            ways = 1
            last_occurrence = {var: 0 for var in variable_counts}
            min_clauses_to_use = 1

            for var, count in variable_counts.items():
                if count % 2 != 0:
                    last_occurrence[var] = 0
                    if last_occurrence[-var] == 0:
                        ways *= 1 - last_occurrence[-var]
                        ways %= modulo
                    else:
                        ways *= (last_occurrence[-var] - last_occurrence[var])
                        ways %= modulo

                    if last_occurrence[-var] - last_occurrence[var] < 0:
                        min_clauses_to_use += 1
                        last_occurrence[-var] = last_occurrence[-var] - last_occurrence[var]
                        ways = (ways // min_clauses_to_use) % modulo
                        min_clauses_to_use = 1

            # Account for clauses that use both occurrence and neg occurrence
            if min_clauses_to_use != 1:
                ways *= (last_occurrence[-var] - (num_variables // 2)) % modulo
                ways %= modulo
            return (1 - ways) % modulo

        return sum(compute_expression_once() for clause in self.clauses) % modulo

