def min_path_length(city1, city2, graph):
    distances = {}
    operations = []
    for v1, v2, weight in graph:
        if v1 == city2 or v2 == city2:
            heapq.heappush(operations, (weight, v1, v2))
            distances[v1] = weight
        else:
            heapq.heappush(operations, (weight, v1, v2))
            distances[v2] = weight

    current = city2
    steps = 0

    while current != city1:
        if current in distances:
            path = []
            weight = float('inf')
            while current != city1:
                found = False
                for (to, step, weight) in operations:
                    if to == current and step <= weight:
                        operations.remove((to, step, weight))
                        operations.insert(0, (to, step + 1, weight))
                        weight = step + 1
                        path.append((to, step + 1, weight))
                        found = True
                        break
                if found:
                    current = to
                        steps += 1
                        continue

            if steps >= 0:
                for to, step, weight in path:
                    print(f"{step + 1} {weight + 1},", end=' ')
        else:
            print("0, ", end=' ')

    return steps

