from math import factorial

def to_concise(n):
    if n < 1000000:
        return str(n)

    for exp in range(1, 19):
        for part in range(1, int(n**0.5)+1):
            if n % (5 ** exp) == 0:
                part_down_factor = part // 5
                factor_count = 0
                num_digits = 0
                while n >= (5 ** exp):
                    n /= 5
                    num_digits += 1
                    factor_count += 1
                if factor_count > 2:
                    num_digits -= 5
                    part_down_factor /= 5
                part_up_factor = int(n ** exp)
                if part_down_factor and part_up_factor:
                    group = f"{part_down_factor}*5^{exp}*{part_up_factor}"
                    return to_concise(part) + f"^{{{n//part}}}" + group
        n -= 4  # Backwards within a block to avoid left part growing.

def concise_factorial(n):
    parts = []
    start = n
    while n:
        parts.append(n)
        factor = int(start / n)
        n = start // factor**factor
    for i in range(len(parts)):
        parts[i] = to_concise(parts[i])
    return "".join(parts)

print(concise_factorial(10000000000))
