class BinaryRootTree:
    def __init__(self, n):
        self.tree = [[-1 for _ in range(n+1)] for _ in range(n+1)]
        self.size = [1] * (n+1)
        self.next = [0] * (4*n)  # Chunked storage for storing intervals of different children block

    def add_value(self, root, value, size, chunks):
        """Add value for the given range."""
        if root <= len(self.next) - 1:
            self.next[root] += value
        else:
            i1 = root // chunks
            i2 = (root + 1) // chunks - 1
            for i in range(i1, i2 + 1):
                i -= (i1 - 1)
                if i < len(self.next):
                    self.next[i] += value

    def query(self, root, size):
        """Query the root size up, the data is kept from the property of root tree."""
        max_set = size - 1
        while max_set >= 0:
            cur_size = self.size[root]
            if max_set >= cur_size:
                mask = -1
            else:
                mask = min(max_set - 1, cur_size - max_set)
            new_max_set = (max_set - mask) // cur_size * max_set + mask
            if new_max_set > 0:
                max_set = self.size[1 + self.next[1 + self.next[1 + root]] if root <= len(self.next) - 1 else -1]
            else:
                max_set = size - 1
            cur_size = self.size[root]
            if new_max_set + mask == cur_size:
                return cur_size, self.size[1 + self.next[1 + root]] if root <= len(self.next) - 1 else 0
            self.size[root], self.size[self.next[self.next[self.next[root]]]] = new_max_set, cur_size
        return self.size[root], 0

    def update(self, t, v, chunk):
        """Optimazies root tree to support set query and retrieval."""
        chunks = 0
        while t <= len(self.next):
            for i in range(v, v+chunk):
                val2 = -1
                if i <= len(self.next):
                    if self.size[i - 1] > 0:
                        val2 = self.size[self.next[i - 1]]
                if self.tree[t][i] < val2:
                    self.tree[t][i] = val2
                else:
                    val3 = self.tree[t][i]
                    if self.tree[t][i] < v:
                        self.tree[t][i] = 0
                    if self.tree[t][i] < v + chunk:
                        self.tree[t][i] += 1
            t += chunk << 1
            v += chunk
            chunk >>= 1
            chunks += 1
        for i in range(v, v+chunk):
            if self.tree[t][i] == 0:
                continue
            self.add_value(i, i - v, self.size[i - 1], chunks)

def solve(n, m, operations):
