from collections import defaultdict

def build_graph(n, labels):
    graph = defaultdict(list)
    child_to_parent = [index for index, label in enumerate(labels) if label != 0]
    for i in range(1, n + 1):
        current = labels[i-1]
        if labels[i] != 0:
            graph[labels[i-1]].append(labels[i-1] + labels[i])
            if i not in child_to_parent:
                graph[labels[i-1]].append(labels[i-1] + current)
    return graph

def lexicographically_smallest_representation(graph):
    def dfs(node, path):
        path_backup = path
        for value in graph[node]:
            if path_backup + value > path + value:
                dfs(value, path + value)
        return None

    path = 0
    while True:
        result = dfs(path, '')
        if not result:
            break
        path = result + path + value

    return path

