    n = len(crossword)
    dp = [[-1] * n for _ in range(n + 1)]

    for i in range(n - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if dp[i][j] == -1:
                continue

            for word in word_list:
                if crossword[i:j + 1] == word:
                    dp[i][j] = max(dp[i][j], dp[i + word_list.index(word) - 1][j + 1] + point_list[word_list.index(word)])

            for k in range(min(x, j + 1)):
                if dp[i + k + 1][j] == -1:
                    continue

                if dp[i][j]:
                    dp[i][j] = max(dp[i][j], dp[i + k + 1][j] + point_list[word_list.index(word_list[0])])

        dp[i][j] = max(dp[i][j], dp[i][j + 1])

    return max(dp[0])

