import math

def expectation_of_inversions(n, permutation):
    expected_inversions = 0
    for i in range(n):
        for j in range(i + 1, n):
            count = 0
            for k in range(i, j + 1):
                if permutation[k - 1] > permutation[j - i]:
                    count += 1
            expected_inversions += count * math.comb(j - i, 2)
    return expected_inversions / math.factorial(n)

