def max_points crossword, words, word_map, k):
    n = len(crossword)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = 1
    max_points = 0
    for word in words:
        if crossword.startswith(word, 0, len(word)):
            dp[len(word)][len(word)] = word_map[word]
            max_points = max(max_points, dp[len(word)][len(word)])
    for length in range(1, n + 1):
        for start in range(n - length + 1):
            end = start + length
            if crossword[start - 1] == crossword[end - 1]:
                dp[start][end] += dp[start - 1][start + length - 2]
            for word in words:
                if crossword.startswith(word, start, end):
                    dp[start][end] = max(dp[start][end], dp[start][start + len(word) - 1] + word_map[word])
                    if dp[start][start + len(word) - 1] + word_map[word] > max_points:
                        max_points = dp[start][start + len(word) - 1] + word_map[word]
    if max_points > 0:
        return max_points * k
    else:
        return 0

