def sort_and_partition(arr):
    """
    Sorts the array partitioned in increasing and decreasing subsequences and prints the count of partitions.
    """
    decreasing = []
    increasing = []
    for num in arr:
        i = bisect_right(decreasing, num)
        if i == len(decreasing):
            insort(decreasing, num)
        else:
            insort(increasing, num)

