            i += 1
    return ''.join(ans)

def lca(x, y):
    while y:
        if x == y or (x > y):
            return y
        y = y.p
    return x

def duplicate(at,belongs):
    if belongs > 0:
        return list(at * 2)
    else:
        if at.b_l == 0 or at.b_r == 0:
            return list(0 * 2)
        else:
            return list(["0"] * (len(at) * 2))

def process(n,k):
    if n>2*k+1:
        return n * ['a']
    ji = [1]
    for i in range(1,n // 2):
        n2 = i * 2 - ji[-1]
        if ji[n2]!=0:
            if ji[-1]==0:
                ji.append(ji[-1] + 1)
            else:
                ji.append(ji[-1])
        else:
            ji.append(ji[-1]+1)
    num_char = ji[-1]
    if n == 1 and k == 0:
        return ["a"]
    elif ji[-1] == n:
        return ["a"] * n
    else:
        for i in range(len(ji) - 1, -1, -1):
            n2 = ji[i]
            q = deque()
            for j in range(i):
                if j == len(q):
                    q.extend(duplicate(q[-1], k - 1))

                else:
                    if q[j].b_l == 0 or q[j].b_r == 0:
                        q[j].b_l = lca(q[j].s, q[j].b_l)
                        q[j].b_r = lca(q[j].s, q[j].b_r)
                        q.extend(duplicate(q[j], 1))

                    else:
                        q[j].b_l = lca(q[j].b_l, q[j].b_l)
                        q[j].b_r = lca(q[j].b_r, q[j].b_r)
                        if q[j].b_l == 0 or q[j].b_r != 0:
                            q[j].b_l = 0
                        if q[j].b_r == 0:
                            q[j].b_r = 0
                        q.extend(duplicate(q[j], 0))
                n2 -= len(q)
                while n2 >= 0 and q:
                    q.pop()
                    n2 -= len(q)
            q.extend(list(['0'] * (num_char-len(q))))
            ji[i] = len(q)
        while len(q) != ji[num_char]:
            q.append('0')

        return 'a' * num_char

