MOD = 10**9 + 7

def calculate_ways(clauses, variables):
    def dominates(x, y):
        return x & y == 0

    def turn(clauses, variables):
        result = [0] * variables
        for clause in clauses:
            right = deque(clause + [0] * (2 - len(clause)))
            for i in range(len(right)):
                count = right.popleft() or result[-len(right) + i]
                if count:
                    j = variables.index(i + 1)
                    result[j] |= 1 << (len(right) - 1 - j)
                    result[j] &= ~result[-len(right) + j]
        return result

    return turn(reversed(list(clauses)), variables)

def init_view():
    n, m = map(int, input().split())
    variables = list(range(1, m + 1))
    clauses = []
    for i in range(n):
        k, a = map(int, input().split())
        jumps = [0] * (k - 1) + [1] + [-1] * (k - 1)
        for j in range(a):
            par, znak = map(int, input().split())
            par -= 1
            if znak:
                jumps[par] |= 1 << -j
            else:
                jumps[par] &= ~(1 << -j)
        clauses.append([[jumps[0] >> i & 1 for i in range(k)] for k in jumps])
    return turn(init_view(), variables)

