from collections import Counter

def xor_clause(a, b):  # checks if two literals are XORd
    if a > 0 and b < 0: return True
    if a < 0 and b > 0: return True
    return False

def solve(num_var, clauses):
    count = Counter()
    for i, clause in enumerate(clauses):
        literals = []
        for a in clause[:-1]:  # all '>=1', anchor it
            if xor_clause(a, num_var) or (a > 0 and & ~a == 0):
                count[num_var], count[-num_var] = min(2, count[num_var] + 1), min(2, count[-num_var] + 1)
            elif a > 0:
                literals.append(a-1)
            else:
                literals.append(-abs(a))
        counter_of_literals_in_cons = Counter(literals)
        for lit, cnt in counter_of_literals_in_cons.items():
            for k in range(1, cnt-1):
                count[lit] = min(2, count[lit] + k)
    return int(pow(2, sum(count.values()), 1000000007))  # inclusive powers mod 10^9 + 7

