    def dfs(index, remains, can_triple):
        if (index, remains, can_triple) in visited:
            return visited[(index, remains, can_triple)]
        if can_triple:
            # Take care of people before you
            if (index // max_turns) % 2 == 0:
                # You're in the odd spot -> here you go
                visited[(index, remains, can_triple)] = 1
            elif dfs(index - 1, remains, True) == 1:
                visited[(index, remains, can_triple)] = 1
            else:
                visited[(index, remains, can_triple)] = 2
        else:
            if dfs(index - 1, remains, True) == 1:
                visited[(index, remains, can_triple)] = 1
            else:
                visited[(index, remains, can_triple)] = 2
        return visited[(index, remains, can_triple)]

    return dfs(count - 1, max_turns - 1, False)
